import React from "react";
import { graphql, Link, type HeadFC } from "gatsby";
import Layout from "../components/Layout";
import SEO from "../components/seo";

const NotFoundPage: React.FC = () => (
  <Layout>
    <div
      className="cc-container flex flex-col items-center justify-center text-center"
      style={{ minHeight: "80vh", paddingTop: "var(--space-10)", paddingBottom: "var(--space-10)" }}
    >
      <span className="text-mono" style={{ fontSize: 14 }}>404</span>
      <h1 className="text-display mt-4">Page not found</h1>
      <p className="text-lg-body mt-4" style={{ maxWidth: 480 }}>
        The page you are looking for does not exist or has been moved.
      </p>
      <div className="flex flex-wrap gap-3 justify-center mt-8">
        <Link to="/" className="btn-primary">Go home</Link>
        <Link to="/contact/" className="btn-secondary">Contact us</Link>
      </div>
    </div>
  </Layout>
);

export default NotFoundPage;

export const Head: HeadFC = ({ data, location }: any) => (
  <SEO
    data={data.allDataJson.nodes[0]}
    title="404 - Page Not Found · Code Crafted"
    description="The page you are looking for does not exist or has been moved."
    language={data.locales?.edges?.[0]?.node?.language}
    originalPath={location.pathname}
    noindex
  />
);

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges { node { ns data language } }
    }
    allDataJson {
      nodes {
        companyName address city province country postalCode
        phone email instagram facebook linkedin whatsapp url
        founder { name jobTitle sameAs }
      }
    }
  }
`;
